fs.writeFileSync(base+"/Billing.tsx",'import { useState, useEffect, useCallback } from \'react\'\nimport { motion } from \'framer-motion\'\nimport { DollarSign, CreditCard, RefreshCw, CheckCircle2, Clock, AlertCircle, Zap, TrendingUp, FileText } from \'lucide-react\'\nimport { Button } from \'@/components/ui/button\'\nimport { AnimatedCounter } from \'@/components/AnimatedCounter\'\nimport { db, SUPABASE_FUNCTIONS_URL } from \'@/lib/supabase\'\nimport { formatCurrency, timeAgo } from \'@/lib/utils\'\nimport { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from \'recharts\'\n\nconst statusStyle: Record<string, string> = {\n  paid:     \'bg-emerald-500/10 text-emerald-400 border-emerald-500/30\',\n  pending:  \'bg-amber-500/10 text-amber-400 border-amber-500/30\',\n  in_fulfillment: \'bg-cyan/10 text-cyan border-cyan/30\',\n  failed:   \'bg-red-500/10 text-red-400 border-red-500/30\',\n  refunded: \'bg-violet/10 text-violet border-violet/30\',\n}\n\nexport default function Billing() {\n  const [orders, setOrders] = useState<any[]>([])\n  const [stripeEvents, setStripeEvents] = useState<any[]>([])\n  const [loading, setLoading] = useState(true)\n  const [triggering, setTriggering] = useState(false)\n  const [triggerResult, setTriggerResult] = useState<{ok:boolean;msg:string}|null>(null)\n  const [activeTab, setActiveTab] = useState<\'orders\'|\'stripe\'>(\'orders\')\n\n  const load = useCallback(async () => {\n    setLoading(true)\n    try {\n      const [ordersRes, stripeRes] = await Promise.allSettled([\n        db.deals.from(\'work_orders\')\n          .select(\'id,client_name,business_name,email,package,total_amount,deposit_amount,monthly_amount,status,payment_status,paid_at,signed_at,fulfillment_status,execution_status,proposal_id,service_type,created_at,cancellation_deadline,probation_ends_at\')\n          .order(\'created_at\', { ascending: false }).limit(50),\n        db.deals.from(\'stripe_webhook_events\')\n          .select(\'id,event_type,amount,currency,status,customer_email,created_at\')\n          .order(\'created_at\', { ascending: false }).limit(30),\n      ])\n      if (ordersRes.status === \'fulfilled\') setOrders(ordersRes.value.data || [])\n      if (stripeRes.status === \'fulfilled\') setStripeEvents(stripeRes.value.data || [])\n    } catch (e) { console.error(e) }\n    finally { setLoading(false) }\n  }, [])\n\n  useEffect(() => { load() }, [load])\n\n  const triggerStripeTest = async () => {\n    setTriggering(true)\n    setTriggerResult(null)\n    try {\n      const res = await fetch(`${SUPABASE_FUNCTIONS_URL}/stripe-webhook`, {\n        method: \'POST\',\n        headers: { \'Content-Type\': \'application/json\' },\n        body: JSON.stringify({ type: \'payment_intent.succeeded\', data: { object: { amount: 75000, currency: \'usd\' } } }),\n      })\n      const data = await res.json()\n      setTriggerResult({ ok: res.ok, msg: data?.message || (res.ok ? \'Stripe test event fired\' : \'Error\') })\n      if (res.ok) setTimeout(load, 1500)\n    } catch (e: any) { setTriggerResult({ ok: false, msg: e.message }) }\n    finally { setTriggering(false) }\n  }\n\n  const stats = {\n    total: orders.length,\n    paid: orders.filter(o => o.payment_status === \'paid\').length,\n    pending: orders.filter(o => o.payment_status === \'pending\').length,\n    mrr: orders.filter(o => o.payment_status === \'paid\').reduce((s, o) => s + parseFloat(o.monthly_amount || o.total_amount || 0), 0),\n  }\n\n  const chartData = (() => {\n    const byDay: Record<string, number> = {}\n    orders.filter(o => o.paid_at).forEach(o => {\n      const d = new Date(o.paid_at).toLocaleDateString(\'en-US\', { month: \'short\', day: \'numeric\' })\n      byDay[d] = (byDay[d] || 0) + parseFloat(o.monthly_amount || o.total_amount || 0)\n    })\n    return Object.entries(byDay).slice(-7).map(([name, revenue]) => ({ name, revenue }))\n  })()\n\n  return (\n    <div className="space-y-6">\n      <div className="flex items-center justify-between">\n        <div>\n          <h2 className="text-xl font-bold text-foreground flex items-center gap-2">\n            <DollarSign className="w-5 h-5 text-cyan" /> Billing & Payments\n          </h2>\n          <p className="text-xs text-muted-foreground mt-0.5">deals.work_orders · Stripe webhook events</p>\n        </div>\n        <div className="flex gap-2">\n          <Button variant="outline" size="sm" className="border-border/40 text-xs h-8" onClick={load} disabled={loading}>\n            <RefreshCw className={`w-3.5 h-3.5 mr-1.5 ${loading ? \'animate-spin\' : \'\'}`} />Refresh\n          </Button>\n          <Button size="sm" className="bg-gradient-primary text-space font-bold text-xs h-8" onClick={triggerStripeTest} disabled={triggering}>\n            <Zap className="w-3.5 h-3.5 mr-1.5" />{triggering ? \'Firing...\' : \'Test Stripe Event\'}\n          </Button>\n        </div>\n      </div>\n\n      {triggerResult && (\n        <div className={`p-3 rounded-xl border text-xs ${triggerResult.ok ? \'bg-emerald-500/10 border-emerald-500/20 text-emerald-400\' : \'bg-red-500/10 border-red-500/20 text-red-400\'}`}>\n          {triggerResult.ok ? \'✓\' : \'✗\'} {triggerResult.msg}\n        </div>\n      )}\n\n      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">\n        {[\n          { label: \'Work Orders\', value: stats.total,   icon: FileText,    color: \'text-cyan\' },\n          { label: \'Paid\',        value: stats.paid,    icon: CheckCircle2, color: \'text-emerald-400\' },\n          { label: \'Pending\',     value: stats.pending, icon: Clock,       color: \'text-amber-400\' },\n          { label: \'Est. MRR\',    value: stats.mrr,     icon: TrendingUp,  color: \'text-violet\', isCurrency: true },\n        ].map((m, i) => (\n          <motion.div key={m.label} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}\n            className="p-4 rounded-2xl bg-card border border-border/40 card-glow">\n            <div className="flex items-center gap-2 mb-2">\n              <m.icon className={`w-4 h-4 ${m.color}`} />\n              <span className="text-[10px] text-muted-foreground uppercase tracking-wider">{m.label}</span>\n            </div>\n            <div className={`text-2xl font-bold font-mono ${m.color}`}>\n              {loading ? <div className="h-8 w-16 bg-muted/30 rounded animate-pulse" /> :\n                m.isCurrency ? `$${(m.value/1000).toFixed(1)}K` : <AnimatedCounter end={m.value} />}\n            </div>\n          </motion.div>\n        ))}\n      </div>\n\n      {chartData.length > 0 && (\n        <div className="p-5 rounded-2xl bg-card border border-border/40 card-glow">\n          <h3 className="font-semibold text-foreground text-sm mb-4">Revenue Activity</h3>\n          <ResponsiveContainer width="100%" height={140}>\n            <AreaChart data={chartData}>\n              <defs><linearGradient id="revGrad" x1="0" y1="0" x2="0" y2="1">\n                <stop offset="0%" stopColor="#00F0FF" stopOpacity={0.25} />\n                <stop offset="100%" stopColor="#00F0FF" stopOpacity={0} />\n              </linearGradient></defs>\n              <CartesianGrid strokeDasharray="3 3" stroke="rgba(148,163,184,0.08)" vertical={false} />\n              <XAxis dataKey="name" tick={{ fill: \'#94A3B8\', fontSize: 11 }} axisLine={false} tickLine={false} />\n              <YAxis tick={{ fill: \'#94A3B8\', fontSize: 11 }} axisLine={false} tickLine={false} tickFormatter={v => `$${v/1000}K`} />\n              <Tooltip formatter={(v: any) => formatCurrency(v)} />\n              <Area type="monotone" dataKey="revenue" stroke="#00F0FF" strokeWidth={2} fill="url(#revGrad)" />\n            </AreaChart>\n          </ResponsiveContainer>\n        </div>\n      )}\n\n      <div className="flex gap-1 p-1 bg-card border border-border/40 rounded-xl w-fit">\n        {[[\'orders\', \'Work Orders\'], [\'stripe\', \'Stripe Events\']] .map(([id, label]) => (\n          <button key={id} onClick={() => setActiveTab(id as any)}\n            className={`px-4 py-1.5 rounded-lg text-xs font-medium transition-all ${activeTab === id ? \'bg-cyan/10 text-cyan border border-cyan/20\' : \'text-muted-foreground hover:text-foreground\'}`}>\n            {label}\n          </button>\n        ))}\n      </div>\n\n      {activeTab === \'orders\' && (\n        <div className="rounded-2xl bg-card border border-border/40 overflow-hidden">\n          <div className="grid grid-cols-[1fr_auto_auto_auto_auto] gap-3 px-4 py-2 border-b border-border/20 text-[10px] text-muted-foreground uppercase tracking-wider">\n            <span>Client</span><span>Package</span><span>Amount</span><span>Status</span><span>Date</span>\n          </div>\n          {loading ? <div className="p-8 text-center text-muted-foreground text-sm">Loading...</div> :\n            <div className="divide-y divide-border/10 max-h-96 overflow-y-auto">\n              {orders.map((o, i) => (\n                <div key={o.id} className="grid grid-cols-[1fr_auto_auto_auto_auto] gap-3 px-4 py-2.5 hover:bg-space-highlight/20 transition-colors items-center">\n                  <div className="min-w-0">\n                    <p className="text-sm font-medium text-foreground truncate">{o.business_name || o.client_name}</p>\n                    <p className="text-[10px] text-muted-foreground truncate">{o.email}</p>\n                  </div>\n                  <p className="text-xs text-muted-foreground">{o.package || o.service_type || \'—\'}</p>\n                  <p className="text-sm font-mono font-bold text-foreground">{formatCurrency(parseFloat(o.monthly_amount || o.total_amount || 0))}</p>\n                  <span className={`text-[10px] px-2 py-0.5 rounded border ${statusStyle[o.payment_status] || statusStyle.pending}`}>\n                    {o.payment_status}\n                  </span>\n                  <span className="text-[10px] text-muted-foreground whitespace-nowrap">{timeAgo(o.created_at)}</span>\n                </div>\n              ))}\n            </div>}\n        </div>\n      )}\n\n      {activeTab === \'stripe\' && (\n        <div className="rounded-2xl bg-card border border-border/40 overflow-hidden">\n          <div className="px-4 py-3 border-b border-border/20"><h3 className="text-sm font-semibold text-foreground">deals.stripe_webhook_events</h3></div>\n          {stripeEvents.length === 0 ? <div className="p-8 text-center text-muted-foreground text-sm">No Stripe events yet. Fire a test event above.</div> :\n            <div className="divide-y divide-border/10 max-h-96 overflow-y-auto">\n              {stripeEvents.map((e, i) => (\n                <div key={e.id || i} className="flex items-center gap-4 px-4 py-2.5 hover:bg-space-highlight/20 transition-colors">\n                  <CreditCard className="w-4 h-4 text-muted-foreground flex-shrink-0" />\n                  <div className="flex-1 min-w-0">\n                    <p className="text-xs font-medium text-foreground">{e.event_type}</p>\n                    <p className="text-[10px] text-muted-foreground">{e.customer_email || \'—\'}</p>\n                  </div>\n                  {e.amount && <p className="text-sm font-mono text-cyan">{formatCurrency(e.amount / 100)}</p>}\n                  <span className="text-[10px] text-muted-foreground">{timeAgo(e.created_at)}</span>\n                </div>\n              ))}\n            </div>}\n        </div>\n      )}\n    </div>\n  )\n}\n',"utf8");console.log("✅ Billing.tsx");
fs.writeFileSync(base+"/WorkOrders.tsx",'import { useState, useEffect, useCallback } from \'react\'\nimport { motion } from \'framer-motion\'\nimport { Briefcase, RefreshCw, CheckCircle2, Clock, AlertCircle, User, Calendar, Zap } from \'lucide-react\'\nimport { Button } from \'@/components/ui/button\'\nimport { AnimatedCounter } from \'@/components/AnimatedCounter\'\nimport { db, SUPABASE_FUNCTIONS_URL } from \'@/lib/supabase\'\nimport { timeAgo } from \'@/lib/utils\'\n\nconst statusStyle: Record<string, string> = {\n  pending:        \'bg-amber-500/10 text-amber-400 border-amber-500/30\',\n  assigned:       \'bg-cyan/10 text-cyan border-cyan/30\',\n  ready_for_rico: \'bg-violet/10 text-violet border-violet/30\',\n  in_progress:    \'bg-blue-500/10 text-blue-400 border-blue-500/30\',\n  complete:       \'bg-emerald-500/10 text-emerald-400 border-emerald-500/30\',\n  cancelled:      \'bg-red-500/10 text-red-400 border-red-500/30\',\n}\n\nexport default function WorkOrders() {\n  const [orders, setOrders]     = useState<any[]>([])\n  const [trackers, setTrackers] = useState<any[]>([])\n  const [loading, setLoading]   = useState(true)\n  const [assigning, setAssigning] = useState(false)\n  const [result, setResult]     = useState<{ok:boolean;msg:string}|null>(null)\n  const [activeTab, setActiveTab] = useState<\'orders\'|\'tracker\'>(\'orders\')\n\n  const load = useCallback(async () => {\n    setLoading(true)\n    try {\n      const [ordersRes, trackRes] = await Promise.allSettled([\n        db.deals.from(\'work_orders\')\n          .select(\'id,client_name,business_name,email,package,service_type,status,payment_status,execution_status,fulfillment_status,assigned_to,priority,created_at,cancellation_deadline,production_released_at,rico_visible\')\n          .order(\'created_at\', { ascending: false }).limit(50),\n        db.rico.from(\'work_order_tracker\')\n          .select(\'id,work_order_id,proposal_id,client_name,business_name,service_type,assigned_to,assigned_at,status,priority,stripe_paid_at,due_date\')\n          .order(\'assigned_at\', { ascending: false }).limit(30),\n      ])\n      if (ordersRes.status === \'fulfilled\') setOrders(ordersRes.value.data || [])\n      if (trackRes.status === \'fulfilled\') setTrackers(trackRes.value.data || [])\n    } catch(e) { console.error(e) }\n    finally { setLoading(false) }\n  }, [])\n\n  useEffect(() => { load() }, [load])\n\n  const triggerRicoAssign = async () => {\n    setAssigning(true)\n    setResult(null)\n    try {\n      const res = await fetch(`${SUPABASE_FUNCTIONS_URL}/core-automation-engine`, {\n        method: \'POST\', headers: { \'Content-Type\': \'application/json\' },\n        body: JSON.stringify({ trigger: \'payment_received\' }),\n      })\n      const data = await res.json()\n      setResult({ ok: res.ok, msg: data?.message || (res.ok ? \'Rico assignment triggered\' : \'Error\') })\n      if (res.ok) setTimeout(load, 2000)\n    } catch (e: any) { setResult({ ok: false, msg: e.message }) }\n    finally { setAssigning(false) }\n  }\n\n  const stats = {\n    total:    orders.length,\n    pending:  orders.filter(o => o.execution_status === \'ready_for_rico\' || o.status === \'pending\').length,\n    assigned: trackers.length,\n    complete: orders.filter(o => o.fulfillment_status === \'complete\').length,\n  }\n\n  return (\n    <div className="space-y-6">\n      <div className="flex items-center justify-between">\n        <div>\n          <h2 className="text-xl font-bold text-foreground flex items-center gap-2">\n            <Briefcase className="w-5 h-5 text-cyan" /> Work Orders — Rico BGE\n          </h2>\n          <p className="text-xs text-muted-foreground mt-0.5">deals.work_orders · rico.work_order_tracker · Payment → Assignment → Fulfillment</p>\n        </div>\n        <div className="flex gap-2">\n          <Button variant="outline" size="sm" className="border-border/40 text-xs h-8" onClick={load} disabled={loading}>\n            <RefreshCw className={`w-3.5 h-3.5 mr-1.5 ${loading ? \'animate-spin\' : \'\'}`} />Refresh\n          </Button>\n          <Button size="sm" className="bg-gradient-primary text-space font-bold text-xs h-8" onClick={triggerRicoAssign} disabled={assigning}>\n            <Zap className="w-3.5 h-3.5 mr-1.5" />{assigning ? \'Assigning...\' : \'Rico: Assign Work\'}\n          </Button>\n        </div>\n      </div>\n\n      {result && (\n        <div className={`p-3 rounded-xl border text-xs ${result.ok ? \'bg-emerald-500/10 border-emerald-500/20 text-emerald-400\' : \'bg-red-500/10 border-red-500/20 text-red-400\'}`}>\n          {result.ok ? \'✓\' : \'✗\'} {result.msg}\n        </div>\n      )}\n\n      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">\n        {[\n          { label: \'Total\',    value: stats.total,    icon: Briefcase,    color: \'text-cyan\' },\n          { label: \'Pending\',  value: stats.pending,  icon: Clock,        color: \'text-amber-400\' },\n          { label: \'Assigned\', value: stats.assigned, icon: User,         color: \'text-violet\' },\n          { label: \'Complete\', value: stats.complete, icon: CheckCircle2, color: \'text-emerald-400\' },\n        ].map((m, i) => (\n          <motion.div key={m.label} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}\n            className="p-4 rounded-2xl bg-card border border-border/40 card-glow">\n            <div className="flex items-center gap-2 mb-2">\n              <m.icon className={`w-4 h-4 ${m.color}`} />\n              <span className="text-[10px] text-muted-foreground uppercase tracking-wider">{m.label}</span>\n            </div>\n            <div className={`text-2xl font-bold font-mono ${m.color}`}>\n              {loading ? <div className="h-8 w-16 bg-muted/30 rounded animate-pulse" /> : <AnimatedCounter end={m.value} />}\n            </div>\n          </motion.div>\n        ))}\n      </div>\n\n      {/* 3-day rule banner */}\n      <div className="p-4 rounded-2xl bg-violet/5 border border-violet/20 flex items-center gap-3">\n        <AlertCircle className="w-5 h-5 text-violet flex-shrink-0" />\n        <div>\n          <p className="text-sm font-semibold text-violet">3-Day Cancellation Rule Active</p>\n          <p className="text-xs text-muted-foreground mt-0.5">Work orders enter fulfillment 3 days after payment. Rico assigns developers only after the probation window closes. Never before payment is confirmed.</p>\n        </div>\n      </div>\n\n      <div className="flex gap-1 p-1 bg-card border border-border/40 rounded-xl w-fit">\n        {[[\'orders\', `Work Orders (${orders.length})`], [\'tracker\', `Rico Tracker (${trackers.length})`]].map(([id, label]) => (\n          <button key={id} onClick={() => setActiveTab(id as any)}\n            className={`px-4 py-1.5 rounded-lg text-xs font-medium transition-all ${activeTab === id ? \'bg-cyan/10 text-cyan border border-cyan/20\' : \'text-muted-foreground hover:text-foreground\'}`}>\n            {label}\n          </button>\n        ))}\n      </div>\n\n      {activeTab === \'orders\' && (\n        <div className="rounded-2xl bg-card border border-border/40 overflow-hidden">\n          <div className="grid grid-cols-[1fr_auto_auto_auto_auto] gap-3 px-4 py-2 border-b border-border/20 text-[10px] text-muted-foreground uppercase tracking-wider">\n            <span>Client</span><span>Service</span><span>Payment</span><span>Execution</span><span>Created</span>\n          </div>\n          {loading ? <div className="p-8 text-center text-muted-foreground text-sm">Loading...</div> :\n            <div className="divide-y divide-border/10 max-h-96 overflow-y-auto">\n              {orders.map(o => (\n                <div key={o.id} className="grid grid-cols-[1fr_auto_auto_auto_auto] gap-3 px-4 py-2.5 hover:bg-space-highlight/20 transition-colors items-center">\n                  <div className="min-w-0">\n                    <p className="text-sm font-medium text-foreground truncate">{o.business_name || o.client_name}</p>\n                    <p className="text-[10px] text-muted-foreground">{o.email}</p>\n                  </div>\n                  <p className="text-xs text-muted-foreground">{o.service_type || o.package || \'—\'}</p>\n                  <span className={`text-[10px] px-2 py-0.5 rounded border ${statusStyle[o.payment_status] || \'bg-muted/10 text-muted-foreground border-border\'}`}>{o.payment_status}</span>\n                  <span className={`text-[10px] px-2 py-0.5 rounded border ${statusStyle[o.execution_status] || \'bg-muted/10 text-muted-foreground border-border\'}`}>{o.execution_status || \'—\'}</span>\n                  <span className="text-[10px] text-muted-foreground whitespace-nowrap">{timeAgo(o.created_at)}</span>\n                </div>\n              ))}\n            </div>}\n        </div>\n      )}\n\n      {activeTab === \'tracker\' && (\n        <div className="rounded-2xl bg-card border border-border/40 overflow-hidden">\n          <div className="px-4 py-3 border-b border-border/20"><h3 className="text-sm font-semibold text-foreground">rico.work_order_tracker</h3></div>\n          {trackers.length === 0 ? <div className="p-8 text-center text-muted-foreground text-sm">No assignments yet. Click "Rico: Assign Work" to trigger assignment.</div> :\n            <div className="divide-y divide-border/10 max-h-96 overflow-y-auto">\n              {trackers.map((t, i) => (\n                <div key={t.id || i} className="flex items-center gap-4 px-4 py-2.5 hover:bg-space-highlight/20 transition-colors">\n                  <div className="flex-1 min-w-0">\n                    <p className="text-sm font-medium text-foreground truncate">{t.business_name || t.client_name}</p>\n                    <p className="text-[10px] text-muted-foreground">{t.service_type} · Assigned to: {t.assigned_to || \'Unassigned\'}</p>\n                  </div>\n                  <span className={`text-[10px] px-2 py-0.5 rounded border ${statusStyle[t.status] || \'bg-muted/10 text-muted-foreground border-border\'}`}>{t.status}</span>\n                  {t.due_date && <span className="text-[10px] text-amber-400 whitespace-nowrap">Due {timeAgo(t.due_date)}</span>}\n                  <span className="text-[10px] text-muted-foreground whitespace-nowrap">{t.assigned_at ? timeAgo(t.assigned_at) : \'—\'}</span>\n                </div>\n              ))}\n            </div>}\n        </div>\n      )}\n    </div>\n  )\n}\n',"utf8");console.log("✅ WorkOrders.tsx");
fs.writeFileSync(base+"/HRZara.tsx",'import { useState, useEffect, useCallback } from \'react\'\nimport { motion } from \'framer-motion\'\nimport { Users, UserPlus, RefreshCw, CheckCircle2, Clock, Mail, Phone, Zap, Shield } from \'lucide-react\'\nimport { Button } from \'@/components/ui/button\'\nimport { Input } from \'@/components/ui/input\'\nimport { AnimatedCounter } from \'@/components/AnimatedCounter\'\nimport { db, SUPABASE_FUNCTIONS_URL } from \'@/lib/supabase\'\nimport { timeAgo } from \'@/lib/utils\'\n\nconst ONBOARDING_PHASES = [\n  \'Apply\', \'Pre-qualified\', \'Contract\', \'Account\', \'Training\',\n  \'Active\', \'Leads\', \'PowerDial\', \'AI Monitor\', \'Payout\'\n]\n\nexport default function HRZara() {\n  const [users, setUsers]     = useState<any[]>([])\n  const [invites, setInvites] = useState<any[]>([])\n  const [onboarding, setOnboarding] = useState<any[]>([])\n  const [loading, setLoading] = useState(true)\n  const [inviting, setInviting] = useState(false)\n  const [inviteResult, setInviteResult] = useState<{ok:boolean;msg:string}|null>(null)\n  const [form, setForm] = useState({ email: \'\', full_name: \'\', phone: \'\', role_key: \'contractor\' })\n  const [activeTab, setActiveTab] = useState<\'team\'|\'invites\'|\'onboarding\'>(\'team\')\n\n  const load = useCallback(async () => {\n    setLoading(true)\n    try {\n      const [usersRes, invitesRes, onboardRes] = await Promise.allSettled([\n        db.hr.from(\'users\').select(\'id,email,role_key,created_at\').order(\'created_at\', { ascending: false }).limit(30),\n        db.hr.from(\'user_invites\').select(\'id,email,role_key,status,invited_at,accepted_at\').order(\'invited_at\', { ascending: false }).limit(20),\n        db.hr.from(\'onboarding_log\').select(\'*\').order(\'created_at\', { ascending: false }).limit(20),\n      ])\n      if (usersRes.status === \'fulfilled\') setUsers(usersRes.value.data || [])\n      if (invitesRes.status === \'fulfilled\') setInvites(invitesRes.value.data || [])\n      if (onboardRes.status === \'fulfilled\') setOnboarding(onboardRes.value.data || [])\n    } catch(e) { console.error(e) }\n    finally { setLoading(false) }\n  }, [])\n\n  useEffect(() => { load() }, [load])\n\n  const sendInvite = async () => {\n    if (!form.email) return\n    setInviting(true)\n    setInviteResult(null)\n    try {\n      const res = await fetch(`${SUPABASE_FUNCTIONS_URL}/zara-onboarding`, {\n        method: \'POST\', headers: { \'Content-Type\': \'application/json\' },\n        body: JSON.stringify({ action: \'invite_contractor\', ...form }),\n      })\n      const data = await res.json()\n      setInviteResult({ ok: res.ok, msg: data?.message || (res.ok ? `Invite sent to ${form.email}` : data?.error || \'Error\') })\n      if (res.ok) { setForm({ email: \'\', full_name: \'\', phone: \'\', role_key: \'contractor\' }); setTimeout(load, 1500) }\n    } catch (e: any) { setInviteResult({ ok: false, msg: e.message }) }\n    finally { setInviting(false) }\n  }\n\n  const stats = {\n    users:    users.length,\n    invites:  invites.filter(i => i.status === \'pending\').length,\n    accepted: invites.filter(i => i.status === \'accepted\').length,\n    active:   users.filter(u => u.role_key === \'contractor\').length,\n  }\n\n  return (\n    <div className="space-y-6">\n      <div className="flex items-center justify-between">\n        <div>\n          <h2 className="text-xl font-bold text-foreground flex items-center gap-2">\n            <Users className="w-5 h-5 text-cyan" /> HR & Onboarding — Zara BGE\n          </h2>\n          <p className="text-xs text-muted-foreground mt-0.5">hr schema · 10-phase contractor onboarding · $650/mo · 30% commission</p>\n        </div>\n        <Button variant="outline" size="sm" className="border-border/40 text-xs h-8" onClick={load} disabled={loading}>\n          <RefreshCw className={`w-3.5 h-3.5 mr-1.5 ${loading ? \'animate-spin\' : \'\'}`} />Refresh\n        </Button>\n      </div>\n\n      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">\n        {[\n          { label: \'Team Members\', value: stats.users,    icon: Users,        color: \'text-cyan\' },\n          { label: \'Pending Invites\', value: stats.invites, icon: Clock,      color: \'text-amber-400\' },\n          { label: \'Accepted\',     value: stats.accepted, icon: CheckCircle2, color: \'text-emerald-400\' },\n          { label: \'BGEs Active\',  value: stats.active,   icon: Shield,       color: \'text-violet\' },\n        ].map((m, i) => (\n          <motion.div key={m.label} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}\n            className="p-4 rounded-2xl bg-card border border-border/40 card-glow">\n            <div className="flex items-center gap-2 mb-2">\n              <m.icon className={`w-4 h-4 ${m.color}`} />\n              <span className="text-[10px] text-muted-foreground uppercase tracking-wider">{m.label}</span>\n            </div>\n            <div className={`text-2xl font-bold font-mono ${m.color}`}>\n              {loading ? <div className="h-8 w-16 bg-muted/30 rounded animate-pulse" /> : <AnimatedCounter end={m.value} />}\n            </div>\n          </motion.div>\n        ))}\n      </div>\n\n      {/* Invite form */}\n      <div className="p-5 rounded-2xl bg-card border border-border/40 card-glow">\n        <div className="flex items-center gap-2 mb-4">\n          <UserPlus className="w-4 h-4 text-cyan" />\n          <h3 className="text-sm font-semibold text-foreground">Invite New BGE — Zara Onboarding</h3>\n        </div>\n        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3 mb-3">\n          {[\n            { key: \'full_name\', placeholder: \'Full Name\', icon: Users },\n            { key: \'email\',     placeholder: \'Email Address\', icon: Mail },\n            { key: \'phone\',     placeholder: \'Phone Number\', icon: Phone },\n          ].map(f => (\n            <div key={f.key} className="relative">\n              <f.icon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />\n              <Input value={(form as any)[f.key]} onChange={e => setForm(p => ({ ...p, [f.key]: e.target.value }))}\n                placeholder={f.placeholder} className="pl-9 bg-card border-border/40 h-9 text-sm" />\n            </div>\n          ))}\n          <select value={form.role_key} onChange={e => setForm(p => ({ ...p, role_key: e.target.value }))}\n            className="h-9 px-3 rounded-lg bg-card border border-border/40 text-foreground text-sm focus:outline-none focus:border-cyan">\n            <option value="contractor">BGE — Contractor</option>\n            <option value="developer">Developer</option>\n            <option value="admin">Admin</option>\n          </select>\n        </div>\n        <div className="flex items-center gap-3">\n          <Button onClick={sendInvite} disabled={inviting || !form.email} className="bg-gradient-primary text-space font-bold text-xs h-9">\n            <Zap className="w-3.5 h-3.5 mr-1.5" />{inviting ? \'Sending via Zara...\' : \'Send Invite via Zara\'}\n          </Button>\n          {inviteResult && (\n            <p className={`text-xs ${inviteResult.ok ? \'text-emerald-400\' : \'text-red-400\'}`}>\n              {inviteResult.ok ? \'✓\' : \'✗\'} {inviteResult.msg}\n            </p>\n          )}\n        </div>\n      </div>\n\n      {/* 10-phase onboarding visual */}\n      <div className="p-5 rounded-2xl bg-card border border-border/40 card-glow">\n        <h3 className="text-sm font-semibold text-foreground mb-4">10-Phase BGE Onboarding Flow</h3>\n        <div className="flex items-center gap-1 flex-wrap">\n          {ONBOARDING_PHASES.map((phase, i) => (\n            <div key={phase} className="flex items-center gap-1">\n              <div className="px-3 py-1.5 rounded-lg bg-space-highlight border border-border/30 text-[10px] font-medium text-muted-foreground">\n                <span className="text-cyan mr-1">{i + 1}.</span>{phase}\n              </div>\n              {i < ONBOARDING_PHASES.length - 1 && <span className="text-muted-foreground text-[10px]">→</span>}\n            </div>\n          ))}\n        </div>\n        <div className="mt-3 grid grid-cols-3 gap-3 text-[10px] text-muted-foreground">\n          <p>• 24h contact rule after lead assigned</p>\n          <p>• 3-day inactivity = lead reassigned</p>\n          <p>• 10-day close window per lead</p>\n          <p>• 70 leads max per BGE at once</p>\n          <p>• $650/mo platform fee</p>\n          <p>• 30% commission + residuals</p>\n        </div>\n      </div>\n\n      <div className="flex gap-1 p-1 bg-card border border-border/40 rounded-xl w-fit">\n        {[[\'team\', `Team (${users.length})`], [\'invites\', `Invites (${invites.length})`], [\'onboarding\', `Onboarding Log`]].map(([id, label]) => (\n          <button key={id} onClick={() => setActiveTab(id as any)}\n            className={`px-4 py-1.5 rounded-lg text-xs font-medium transition-all ${activeTab === id ? \'bg-cyan/10 text-cyan border border-cyan/20\' : \'text-muted-foreground hover:text-foreground\'}`}>\n            {label}\n          </button>\n        ))}\n      </div>\n\n      {activeTab === \'team\' && (\n        <div className="rounded-2xl bg-card border border-border/40 overflow-hidden">\n          {users.length === 0 ? <div className="p-8 text-center text-muted-foreground text-sm">No team members yet. Send invites above.</div> :\n            <div className="divide-y divide-border/10 max-h-80 overflow-y-auto">\n              {users.map(u => (\n                <div key={u.id} className="flex items-center gap-4 px-4 py-2.5 hover:bg-space-highlight/20 transition-colors">\n                  <div className="w-8 h-8 rounded-full bg-cyan/10 flex items-center justify-center text-xs font-bold text-cyan flex-shrink-0">\n                    {u.email?.[0]?.toUpperCase()}\n                  </div>\n                  <div className="flex-1 min-w-0">\n                    <p className="text-sm font-medium text-foreground truncate">{u.email}</p>\n                    <p className="text-[10px] text-muted-foreground">{u.role_key}</p>\n                  </div>\n                  <span className="text-[10px] text-muted-foreground">{timeAgo(u.created_at)}</span>\n                </div>\n              ))}\n            </div>}\n        </div>\n      )}\n\n      {activeTab === \'invites\' && (\n        <div className="rounded-2xl bg-card border border-border/40 overflow-hidden">\n          {invites.length === 0 ? <div className="p-8 text-center text-muted-foreground text-sm">No invites yet.</div> :\n            <div className="divide-y divide-border/10 max-h-80 overflow-y-auto">\n              {invites.map(inv => (\n                <div key={inv.id} className="flex items-center gap-4 px-4 py-2.5 hover:bg-space-highlight/20 transition-colors">\n                  <Mail className="w-4 h-4 text-muted-foreground flex-shrink-0" />\n                  <div className="flex-1 min-w-0">\n                    <p className="text-sm font-medium text-foreground truncate">{inv.email}</p>\n                    <p className="text-[10px] text-muted-foreground">{inv.role_key}</p>\n                  </div>\n                  <span className={`text-[10px] px-2 py-0.5 rounded border ${inv.status === \'accepted\' ? \'bg-emerald-500/10 text-emerald-400 border-emerald-500/30\' : \'bg-amber-500/10 text-amber-400 border-amber-500/30\'}`}>\n                    {inv.status}\n                  </span>\n                  <span className="text-[10px] text-muted-foreground whitespace-nowrap">{timeAgo(inv.invited_at)}</span>\n                </div>\n              ))}\n            </div>}\n        </div>\n      )}\n\n      {activeTab === \'onboarding\' && (\n        <div className="rounded-2xl bg-card border border-border/40 overflow-hidden">\n          <div className="px-4 py-3 border-b border-border/20"><h3 className="text-sm font-semibold text-foreground">hr.onboarding_log</h3></div>\n          {onboarding.length === 0 ? <div className="p-8 text-center text-muted-foreground text-sm">No onboarding entries yet.</div> :\n            <div className="divide-y divide-border/10 max-h-80 overflow-y-auto">\n              {onboarding.map((o, i) => (\n                <div key={o.id || i} className="flex items-center gap-4 px-4 py-2.5 hover:bg-space-highlight/20 transition-colors">\n                  <div className="flex-1 min-w-0">\n                    <p className="text-sm font-medium text-foreground">{o.email || o.full_name || \'BGE\'}</p>\n                    <p className="text-[10px] text-muted-foreground">Phase {o.phase} · {o.status}</p>\n                  </div>\n                  <span className="text-[10px] text-muted-foreground">{timeAgo(o.sent_at || o.created_at)}</span>\n                </div>\n              ))}\n            </div>}\n        </div>\n      )}\n    </div>\n  )\n}\n',"utf8");console.log("✅ HRZara.tsx");
fs.writeFileSync(base+"/Reports.tsx",'import { useState, useEffect, useCallback } from \'react\'\nimport { motion } from \'framer-motion\'\nimport { BarChart3, RefreshCw, TrendingUp, Users, DollarSign, Phone } from \'lucide-react\'\nimport { Button } from \'@/components/ui/button\'\nimport { AnimatedCounter } from \'@/components/AnimatedCounter\'\nimport { db } from \'@/lib/supabase\'\nimport { formatCurrency } from \'@/lib/utils\'\nimport { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from \'recharts\'\n\nexport default function Reports() {\n  const [repPerf, setRepPerf]   = useState<any[]>([])\n  const [pipeline, setPipeline] = useState<any[]>([])\n  const [loading, setLoading]   = useState(true)\n\n  const load = useCallback(async () => {\n    setLoading(true)\n    try {\n      const [repRes, pipeRes] = await Promise.allSettled([\n        db.sales?.from(\'v_rep_performance\').select(\'*\').limit(20).catch(() => ({ data: [] })),\n        db.deals.from(\'pipeline\')\n          .select(\'owner_name,estimated_value,stage,ai_score\')\n          .order(\'estimated_value\', { ascending: false }).limit(50),\n      ])\n      if (repRes.status === \'fulfilled\') setRepPerf((repRes.value as any)?.data || [])\n      if (pipeRes.status === \'fulfilled\') {\n        const data = (pipeRes.value as any)?.data || []\n        // Aggregate by rep\n        const byRep: Record<string, any> = {}\n        data.forEach((d: any) => {\n          const rep = d.owner_name || \'Unassigned\'\n          if (!byRep[rep]) byRep[rep] = { rep_name: rep, deal_count: 0, total_value: 0 }\n          byRep[rep].deal_count++\n          byRep[rep].total_value += parseFloat(d.estimated_value || 0)\n        })\n        setPipeline(Object.values(byRep).sort((a: any, b: any) => b.total_value - a.total_value))\n      }\n    } catch(e) { console.error(e) }\n    finally { setLoading(false) }\n  }, [])\n\n  useEffect(() => { load() }, [load])\n\n  const displayData = repPerf.length > 0 ? repPerf : pipeline\n  const totalPipeline = pipeline.reduce((s, r) => s + r.total_value, 0)\n  const totalDeals    = pipeline.reduce((s, r) => s + r.deal_count, 0)\n  const COLORS = [\'#00F0FF\', \'#8B5CF6\', \'#10B981\', \'#F59E0B\', \'#EF4444\', \'#3B82F6\']\n\n  return (\n    <div className="space-y-6">\n      <div className="flex items-center justify-between">\n        <div>\n          <h2 className="text-xl font-bold text-foreground flex items-center gap-2">\n            <BarChart3 className="w-5 h-5 text-cyan" /> Reports & Performance\n          </h2>\n          <p className="text-xs text-muted-foreground mt-0.5">\n            {repPerf.length > 0 ? \'sales.v_rep_performance\' : \'deals.pipeline aggregated by rep\'}\n          </p>\n        </div>\n        <Button variant="outline" size="sm" className="border-border/40 text-xs h-8" onClick={load} disabled={loading}>\n          <RefreshCw className={`w-3.5 h-3.5 mr-1.5 ${loading ? \'animate-spin\' : \'\'}`} />Refresh\n        </Button>\n      </div>\n\n      <div className="grid grid-cols-2 lg:grid-cols-3 gap-4">\n        {[\n          { label: \'Total Pipeline\',  value: totalPipeline, icon: DollarSign, color: \'text-cyan\',         isCurrency: true },\n          { label: \'Total Deals\',     value: totalDeals,    icon: TrendingUp, color: \'text-emerald-400\' },\n          { label: \'Active Reps\',     value: pipeline.length, icon: Users,   color: \'text-violet\' },\n        ].map((m, i) => (\n          <motion.div key={m.label} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}\n            className="p-4 rounded-2xl bg-card border border-border/40 card-glow">\n            <div className="flex items-center gap-2 mb-2">\n              <m.icon className={`w-4 h-4 ${m.color}`} />\n              <span className="text-[10px] text-muted-foreground uppercase tracking-wider">{m.label}</span>\n            </div>\n            <div className={`text-2xl font-bold font-mono ${m.color}`}>\n              {loading ? <div className="h-8 w-20 bg-muted/30 rounded animate-pulse" /> :\n                m.isCurrency ? `$${(m.value/1000).toFixed(0)}K` : <AnimatedCounter end={m.value} />}\n            </div>\n          </motion.div>\n        ))}\n      </div>\n\n      {/* Bar Chart */}\n      {displayData.length > 0 && (\n        <div className="p-5 rounded-2xl bg-card border border-border/40 card-glow">\n          <h3 className="text-sm font-semibold text-foreground mb-4">Pipeline by Rep</h3>\n          <ResponsiveContainer width="100%" height={200}>\n            <BarChart data={displayData.slice(0, 8)} margin={{ top: 5, right: 10, left: 10, bottom: 5 }}>\n              <CartesianGrid strokeDasharray="3 3" stroke="rgba(148,163,184,0.08)" vertical={false} />\n              <XAxis dataKey="rep_name" tick={{ fill: \'#94A3B8\', fontSize: 10 }} axisLine={false} tickLine={false} />\n              <YAxis tick={{ fill: \'#94A3B8\', fontSize: 10 }} axisLine={false} tickLine={false} tickFormatter={v => `$${v/1000}K`} />\n              <Tooltip formatter={(v: any) => formatCurrency(v)} />\n              <Bar dataKey="total_value" name="Pipeline Value" radius={[4, 4, 0, 0]}>\n                {displayData.slice(0, 8).map((_: any, i: number) => (\n                  <Cell key={i} fill={COLORS[i % COLORS.length]} />\n                ))}\n              </Bar>\n            </BarChart>\n          </ResponsiveContainer>\n        </div>\n      )}\n\n      {/* Leaderboard */}\n      <div className="rounded-2xl bg-card border border-border/40 overflow-hidden">\n        <div className="px-4 py-3 border-b border-border/20 flex items-center justify-between">\n          <h3 className="text-sm font-semibold text-foreground">Rep Leaderboard</h3>\n          <span className="text-[10px] text-muted-foreground">By pipeline value</span>\n        </div>\n        {loading ? <div className="p-8 text-center text-muted-foreground text-sm">Loading...</div> :\n          displayData.length === 0 ? <div className="p-8 text-center text-muted-foreground text-sm">No rep data found</div> :\n          <div className="divide-y divide-border/10">\n            {displayData.slice(0, 10).map((r: any, i: number) => (\n              <div key={r.rep_name || i} className="flex items-center gap-4 px-4 py-3 hover:bg-space-highlight/20 transition-colors">\n                <div className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold flex-shrink-0 ${i === 0 ? \'bg-yellow-400/20 text-yellow-400\' : i === 1 ? \'bg-slate-400/20 text-slate-400\' : i === 2 ? \'bg-amber-700/20 text-amber-600\' : \'bg-muted/20 text-muted-foreground\'}`}>\n                  {i + 1}\n                </div>\n                <div className="flex-1 min-w-0">\n                  <p className="text-sm font-medium text-foreground truncate">{r.rep_name || r.owner_name || \'Unknown\'}</p>\n                  <div className="flex items-center gap-3 mt-0.5">\n                    <div className="flex-1 h-1.5 bg-muted/30 rounded-full overflow-hidden">\n                      <div className="h-full rounded-full" style={{ width: `${Math.min(100, (r.total_value / (displayData[0]?.total_value || 1)) * 100)}%`, backgroundColor: COLORS[i % COLORS.length] }} />\n                    </div>\n                  </div>\n                </div>\n                <div className="text-right">\n                  <p className="text-sm font-bold font-mono text-foreground">{formatCurrency(r.total_value || r.revenue_total || 0)}</p>\n                  <p className="text-[10px] text-muted-foreground">{r.deal_count || r.closes_count || 0} deals</p>\n                </div>\n              </div>\n            ))}\n          </div>}\n      </div>\n    </div>\n  )\n}\n',"utf8");console.log("✅ Reports.tsx");
fs.writeFileSync(base+"/Automation.tsx",'import { useState, useCallback } from \'react\'\nimport { motion } from \'framer-motion\'\nimport { Zap, RefreshCw, CheckCircle2, XCircle, Clock, Activity, Brain, GitBranch, Shield, Globe } from \'lucide-react\'\nimport { Button } from \'@/components/ui/button\'\nimport { SUPABASE_FUNCTIONS_URL } from \'@/lib/supabase\'\nimport { timeAgo } from \'@/lib/utils\'\n\nconst ENGINES = [\n  { id: \'lead_distribution\',  label: \'Lead Distribution\',    engine: \'core-automation-engine\', trigger: \'lead_distribution\',  icon: GitBranch, color: \'text-cyan\',        desc: \'Smart assignment · Daily caps · Fairness scoring\' },\n  { id: \'lead_rotation\',      label: \'Lead Rotation\',        engine: \'core-automation-engine\', trigger: \'lead_rotation\',      icon: RefreshCw, color: \'text-blue-400\',    desc: \'Rotate stale leads · Re-qualify · Re-assign\' },\n  { id: \'payment_received\',   label: \'Payment → Work Order\', engine: \'core-automation-engine\', trigger: \'payment_received\',   icon: CheckCircle2, color: \'text-emerald-400\', desc: \'Stripe paid → Rico assigns → 3-day probation\' },\n  { id: \'sentinel_scan\',      label: \'Sentinel Security Scan\', engine: \'core-automation-engine\', trigger: \'sentinel_scan\',    icon: Shield,    color: \'text-red-400\',     desc: \'RLS audit · Access logging · Auto-suspension\' },\n  { id: \'vox_message\',        label: \'Vox Broadcast\',        engine: \'gizmo-vox-router\',        trigger: null,               icon: Brain,     color: \'text-violet\',      desc: \'Route to Steve or Vox · AI response\' },\n  { id: \'outreach\',           label: \'Outreach Engine\',      engine: \'outreach-engine\',         trigger: null,               icon: Globe,     color: \'text-amber-400\',   desc: \'Revenue Engine · 7-touch sequences · Reply tracking\' },\n]\n\ninterface RunLog { id: string; engine: string; trigger: string; ok: boolean; msg: string; ts: string }\n\nexport default function Automation() {\n  const [logs, setLogs]     = useState<RunLog[]>([])\n  const [running, setRunning] = useState<string | null>(null)\n\n  const fire = useCallback(async (eng: typeof ENGINES[0]) => {\n    setRunning(eng.id)\n    const start = Date.now()\n    try {\n      const body = eng.trigger ? JSON.stringify({ trigger: eng.trigger }) : JSON.stringify({ action: \'ping\' })\n      const res = await fetch(`${SUPABASE_FUNCTIONS_URL}/${eng.engine}`, {\n        method: \'POST\', headers: { \'Content-Type\': \'application/json\' }, body,\n      })\n      const data = await res.json()\n      const entry: RunLog = {\n        id: Math.random().toString(36).slice(2),\n        engine: eng.label, trigger: eng.trigger || \'ping\',\n        ok: res.ok,\n        msg: data?.message || data?.detail || (res.ok ? `Completed in ${Date.now() - start}ms` : `Error ${res.status}`),\n        ts: new Date().toISOString(),\n      }\n      setLogs(l => [entry, ...l.slice(0, 19)])\n    } catch (e: any) {\n      setLogs(l => [{ id: Math.random().toString(36).slice(2), engine: eng.label, trigger: eng.trigger || \'ping\', ok: false, msg: e.message, ts: new Date().toISOString() }, ...l.slice(0, 19)])\n    } finally { setRunning(null) }\n  }, [])\n\n  return (\n    <div className="space-y-6">\n      <div>\n        <h2 className="text-xl font-bold text-foreground flex items-center gap-2">\n          <Zap className="w-5 h-5 text-cyan" /> Automation — Orchestration Engine\n        </h2>\n        <p className="text-xs text-muted-foreground mt-0.5">master-router → core-automation-engine · outreach-engine · rico-engine · authority-engine · intelligence-engine</p>\n      </div>\n\n      {/* Engine grid */}\n      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">\n        {ENGINES.map((eng, i) => (\n          <motion.div key={eng.id} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.07 }}\n            className="p-5 rounded-2xl bg-card border border-border/40 card-glow flex flex-col gap-3">\n            <div className="flex items-start justify-between">\n              <div className="flex items-center gap-3">\n                <div className={`w-10 h-10 rounded-xl bg-space-highlight flex items-center justify-center`}>\n                  <eng.icon className={`w-5 h-5 ${eng.color}`} />\n                </div>\n                <div>\n                  <p className="text-sm font-semibold text-foreground">{eng.label}</p>\n                  <p className="text-[10px] font-mono text-muted-foreground">{eng.engine}</p>\n                </div>\n              </div>\n              {running === eng.id && <div className="w-4 h-4 border-2 border-cyan border-t-transparent rounded-full animate-spin" />}\n            </div>\n            <p className="text-[11px] text-muted-foreground">{eng.desc}</p>\n            <Button size="sm" className={`w-full h-8 text-xs font-bold bg-gradient-primary text-space mt-auto`}\n              onClick={() => fire(eng)} disabled={!!running}>\n              <Zap className="w-3.5 h-3.5 mr-1.5" />\n              {running === eng.id ? \'Running...\' : `Fire ${eng.trigger || \'ping\'}`}\n            </Button>\n          </motion.div>\n        ))}\n      </div>\n\n      {/* Live run log */}\n      <div className="rounded-2xl bg-card border border-border/40 overflow-hidden">\n        <div className="px-4 py-3 border-b border-border/20 flex items-center gap-2">\n          <Activity className="w-4 h-4 text-cyan" />\n          <h3 className="text-sm font-semibold text-foreground">Live Run Log</h3>\n          <span className="text-[10px] text-muted-foreground ml-auto">Session only · {logs.length} runs</span>\n        </div>\n        {logs.length === 0 ? (\n          <div className="p-8 text-center text-muted-foreground text-sm">No runs yet. Fire an engine above.</div>\n        ) : (\n          <div className="divide-y divide-border/10 max-h-64 overflow-y-auto">\n            {logs.map(log => (\n              <div key={log.id} className="flex items-center gap-3 px-4 py-2.5">\n                {log.ok\n                  ? <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400 flex-shrink-0" />\n                  : <XCircle    className="w-3.5 h-3.5 text-red-400 flex-shrink-0" />}\n                <div className="flex-1 min-w-0">\n                  <p className="text-xs font-medium text-foreground">{log.engine} · <span className="font-mono text-cyan">{log.trigger}</span></p>\n                  <p className="text-[10px] text-muted-foreground truncate">{log.msg}</p>\n                </div>\n                <span className="text-[10px] text-muted-foreground whitespace-nowrap">{timeAgo(log.ts)}</span>\n              </div>\n            ))}\n          </div>\n        )}\n      </div>\n\n      {/* Engine map */}\n      <div className="p-5 rounded-2xl bg-card border border-border/40 card-glow">\n        <h3 className="text-sm font-semibold text-foreground mb-4">STARZ-OS Engine Map</h3>\n        <div className="grid grid-cols-2 lg:grid-cols-3 gap-3">\n          {[\n            { name: \'master-router\',          role: \'Gateway\',              color: \'border-cyan/30 text-cyan\' },\n            { name: \'core-automation-engine\', role: \'Orchestration Engine\', color: \'border-violet/30 text-violet\' },\n            { name: \'outreach-engine\',        role: \'Revenue Engine\',       color: \'border-emerald-400/30 text-emerald-400\' },\n            { name: \'rico-engine\',            role: \'Delivery Engine\',      color: \'border-amber-400/30 text-amber-400\' },\n            { name: \'authority-engine\',       role: \'Authority Engine\',     color: \'border-blue-400/30 text-blue-400\' },\n            { name: \'intelligence-engine\',    role: \'Intelligence Engine\',  color: \'border-red-400/30 text-red-400\' },\n          ].map(e => (\n            <div key={e.name} className={`p-3 rounded-xl border ${e.color} bg-space-highlight/30`}>\n              <p className={`text-[10px] font-bold uppercase tracking-wider mb-0.5 ${e.color.split(\' \')[1]}`}>{e.role}</p>\n              <p className="text-[10px] font-mono text-muted-foreground">{e.name}</p>\n            </div>\n          ))}\n        </div>\n      </div>\n    </div>\n  )\n}\n',"utf8");console.log("✅ Automation.tsx");
